// Nœud 3 : extraction des champs.
// Il lit le corps du ticket et le passe en minuscules.
const t = $json;
return { json: { id: t.id, corps: t.corps.toLowerCase(), brut: t.corps } };

// Nœud 4 : filtrage par mots-clés.
// Les catégories sont essayées dans l'ordre où elles sont écrites ci-dessous,
// et la première qui trouve un de ses mots dans le texte l'emporte. La boucle
// s'arrête là.
const MOTS = {"technique": ["connecter", "connexion", "marche plus", "panne", "erreur", "bug", "lent", "plante", "bloque", "acces"], "facturation": ["facture", "facturation", "prelevement", "paiement", "rembours", "virement", "echeance"], "commercial": ["devis", "tarif", "abonnement", "licence", "demonstration", "formation", "module"]};
const c = $json.corps;
let categorie = "autre";
for (const nom of Object.keys(MOTS)) {
  if (MOTS[nom].some(m => c.includes(m))) { categorie = nom; break; }
}
return { json: Object.assign({}, $json, { categorie: categorie }) };

// Nœud 5 : recherche de la réponse type.
const REPONSES = {"technique": "Bonjour, notre equipe technique a bien recu votre signalement. Verifiez d'abord que votre navigateur est a jour. Si le probleme persiste, nous revenons vers vous sous 24 h.", "facturation": "Bonjour, vous retrouvez toutes vos factures dans votre espace client, rubrique Documents. Les prelevements sont effectues le 5 de chaque mois.", "commercial": "Bonjour, merci de votre interet. Un conseiller vous rappelle sous 48 h pour etudier votre besoin.", "autre": "Bonjour, pouvez-vous preciser votre demande ? Nous la transmettrons au bon interlocuteur."};
return { json: Object.assign({}, $json, { reponse: REPONSES[$json.categorie] }) };

// Nœud 6 : mise en forme du message sortant.
return { json: {
  ticket: $json.id,
  categorie: $json.categorie,
  message: $json.reponse,
  envoye_le: new Date().toISOString()
} };
